#!/usr/bin/env bash
# Generates the Helm values files under .render/ from .env.
#
# Everything about "which backend gets which signal" lives here, in one place.
# The generated files are plain YAML — read them, diff them, hand them to a
# colleague. Nothing is hidden behind a templating engine.
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

join_yaml_list() { local IFS=", "; echo "[$*]"; }

render_values() {
  step "Rendering Helm values"
  mkdir -p "${RENDER_DIR}"
  render_demo_values
}

# -----------------------------------------------------------------------------
# OpenTelemetry Demo (+ its bundled collector, which is the fan-out point)
# -----------------------------------------------------------------------------
render_demo_values() {
  local out="${RENDER_DIR}/demo-values.yaml"

  # --- Which exporters land in which pipeline -------------------------------
  local -a tr_exp=() me_exp=() lo_exp=() me_rcv=(otlp kafkametrics span_metrics prometheus/ad)

  if [[ "${KEEP_LOCAL_BACKENDS}" == "true" ]]; then
    tr_exp+=(otlp_grpc/jaeger); me_exp+=(otlp_http/prometheus); lo_exp+=(opensearch)
  fi

  # span_metrics is a connector: the traces pipeline must feed it because the
  # metrics pipeline reads from it. Removing it here breaks the metrics pipeline.
  tr_exp+=(span_metrics)

  if [[ "${DEST_DATADOG}" == "true" ]]; then
    tr_exp+=(datadog/connector datadog); me_exp+=(datadog); lo_exp+=(datadog)
    me_rcv+=(datadog/connector)
  fi
  if [[ "${DEST_SPLUNK_O11Y}" == "true" ]]; then
    tr_exp+=(otlphttp/splunk_o11y); me_exp+=(signalfx)
    # Logs to Splunk Observability Cloud are expected to arrive via Log Observer
    # Connect from the Splunk platform, not via direct ingest. See docs/ARCHITECTURE.md.
  fi
  if [[ "${DEST_SPLUNK_HEC}" == "true" ]]; then
    tr_exp+=(splunk_hec/platform_traces); me_exp+=(splunk_hec/platform_metrics); lo_exp+=(splunk_hec/platform_logs)
  fi
  if [[ "${COLLECTOR_DEBUG_EXPORTER}" == "true" ]]; then
    tr_exp+=(debug); me_exp+=(debug); lo_exp+=(debug)
  fi
  # A pipeline with no exporters is invalid; fall back to debug.
  (( ${#me_exp[@]} )) || me_exp+=(debug)
  (( ${#lo_exp[@]} )) || lo_exp+=(debug)

  # Rolls the collector whenever any destination credential changes.
  local cred_hash
  cred_hash="$(hash_string "${DD_API_KEY}|${SPLUNK_O11Y_ACCESS_TOKEN}|${SPLUNK_HEC_TOKEN}|${SPLUNK_AO_API_KEY}")"

  cat > "${out}" <<HEADER
# GENERATED by scripts/render.sh — edit .env and re-run ./run.sh instead.
#
# Overlay on top of the upstream opentelemetry-demo chart (${OTEL_DEMO_CHART_VERSION}).
# Only pipeline wiring, destination exporters and demo sizing are changed;
# everything else is upstream default.

serviceAccount:
  create: true

components:
  # The chart builds its flagd-config ConfigMap from files baked into the chart,
  # with no values hook to override them. Writing to that ConfigMap with kubectl
  # hands field ownership to kubectl-client-side-apply, and Helm 4's server-side
  # apply then refuses to reclaim it ("conflict with kubectl-client-side-apply").
  # So flagd reads from a ConfigMap this repo owns outright, managed by
  # scripts/chaos.sh. The chart's own flagd-config is left alone, unused.
  flagd:
    additionalVolumes:
      - name: config-ro
        configMap:
          name: otel-demo-flagd-flags

  load-generator:
    envOverrides:
      - name: LOAD_GENERATOR_VUS
        value: "${LOAD_GENERATOR_VUS}"

opentelemetry-collector:
  # Cluster-level instrumentation. The demo enables the first four upstream;
  # logsCollection is added here so container logs reach the same destinations
  # as app telemetry.
  #
  # Kubernetes events are wired by hand below rather than with the
  # presets.kubernetesEvents flag: that preset is only applied in deployment and
  # statefulset mode, and is silently ignored for a DaemonSet collector.
  presets:
    hostMetrics:
      enabled: true
    kubernetesAttributes:
      enabled: true
    kubeletMetrics:
      enabled: true
    clusterMetrics:
      enabled: true
    logsCollection:
      enabled: true
      includeCollectorLogs: false
    annotationDiscovery:
      metrics:
        enabled: true

  # Appended to the rules the presets already generate.
  clusterRole:
    rules:
      - apiGroups: ["events.k8s.io", ""]
        resources: ["events"]
        verbs: ["get", "list", "watch"]
      # The kubeletMetrics preset grants nodes/stats, which covers
      # /stats/summary. Resolving container.id additionally requires the
      # kubelet's /pods endpoint, which RBAC gates behind nodes/proxy —
      # otherwise the receiver logs "403 Forbidden" every scrape. The Splunk
      # distribution grants the same permission for the same reason.
      - apiGroups: [""]
        resources: ["nodes/proxy"]
        verbs: ["get", "list", "watch"]
      # The k8s_cluster receiver watches persistent volumes for storage metrics.
      # The clusterMetrics preset omits them, so the receiver logs a "forbidden"
      # reflector error every few seconds and the storage metrics never appear.
      # The Splunk distribution grants these too.
      - apiGroups: [""]
        resources: ["persistentvolumes", "persistentvolumeclaims"]
        verbs: ["get", "list", "watch"]

  resources:
    limits:
      memory: 800Mi

  # Credentials reach the collector as secretKeyRef env vars, which Kubernetes
  # resolves once at container start. Without this annotation, editing a token
  # in .env and re-running would update the Secret but leave the running pod
  # using the old value. The digest is truncated and one-way.
  podAnnotations:
    otel-demo/credentials-hash: "${cred_hash}"

HEADER

  # --- Secret-backed env vars ------------------------------------------------
  {
    echo "  extraEnvs:"
    echo "    - name: DEPLOYMENT_ENVIRONMENT"
    echo "      value: \"${DEPLOYMENT_ENVIRONMENT}\""
    if [[ "${DEST_DATADOG}" == "true" ]]; then
      cat <<'EOS'
    - name: DD_API_KEY
      valueFrom:
        secretKeyRef:
          name: otel-demo-destinations
          key: datadog-api-key
EOS
    fi
    if [[ "${DEST_SPLUNK_O11Y}" == "true" ]]; then
      cat <<'EOS'
    - name: SPLUNK_O11Y_ACCESS_TOKEN
      valueFrom:
        secretKeyRef:
          name: otel-demo-destinations
          key: splunk-o11y-access-token
EOS
    fi
    if [[ "${DEST_SPLUNK_HEC}" == "true" ]]; then
      cat <<'EOS'
    - name: SPLUNK_HEC_TOKEN
      valueFrom:
        secretKeyRef:
          name: otel-demo-destinations
          key: splunk-hec-token
EOS
    fi
    if [[ "${DEST_SPLUNK_AO}" == "true" ]]; then
      cat <<'EOS'
    - name: SPLUNK_AO_API_KEY
      valueFrom:
        secretKeyRef:
          name: otel-demo-destinations
          key: splunk-ao-api-key
EOS
    fi
    echo
  } >> "${out}"

  # --- Collector config: processors ------------------------------------------
  # --- Splunk-shaped Kubernetes telemetry ------------------------------------
  # Splunk's Kubernetes navigator and APM->infrastructure correlation expect the
  # receiver configuration the Splunk distro ships, not the upstream defaults.
  # The distro splits this across two collectors (agent + cluster receiver); the
  # same result is achievable in one, because the signalfx exporter's default
  # translation rules only rewrite host metrics (system.*, cpu.*, memory.*) and
  # are a no-op for k8s.* — which is why the distro's
  # `disable_default_translation_rules` on its cluster receiver is not needed here.
  local k8s_receiver_extras=""
  if [[ "${DEST_SPLUNK_O11Y}" == "true" ]]; then
    # metadata_exporters is the important one: it pushes Kubernetes object
    # metadata (labels, properties, workload relationships) to Splunk as
    # dimension properties. Metrics alone give you charts with nothing to
    # navigate or correlate against.
    k8s_receiver_extras="
        metadata_exporters: [signalfx]"
  fi

  # Datadog's Kubernetes Explorer is fed by Kubernetes *object manifests*, not
  # metrics. A second k8sobjects instance pulls the inventory on the 3m cadence
  # the Explorer requires, kept separate from the events receiver above so that
  # manifests never leak into the container-log pipeline (and onto Splunk's HEC
  # bill). RBAC for these object types is already granted by the clusterMetrics
  # preset plus the rules added below.
  local dd_objects_receiver=""
  if [[ "${DEST_DATADOG}" == "true" ]]; then
    dd_objects_receiver="
      k8sobjects/datadog:
        interval: 3m
        objects:
          - name: pods
            mode: pull
          - name: nodes
            mode: pull
          - name: namespaces
            mode: pull
          - name: services
            mode: pull
          - name: deployments
            group: apps
            mode: pull
          - name: replicasets
            group: apps
            mode: pull
          - name: daemonsets
            group: apps
            mode: pull
          - name: statefulsets
            group: apps
            mode: pull
          - name: jobs
            group: batch
            mode: pull
          - name: cronjobs
            group: batch
            mode: pull"
  fi

  cat >> "${out}" <<PROC
  config:
    receivers:${dd_objects_receiver}
      # Mirrors the Splunk distro's cluster receiver configuration.
      k8s_cluster:
        auth_type: serviceAccount${k8s_receiver_extras}
        metrics:
          k8s.container.status.reason:
            enabled: true
          k8s.node.condition:
            enabled: true
          k8s.pod.status_reason:
            enabled: true
        resource_attributes:
          k8s.hpa.scaletargetref.kind:
            enabled: true
          k8s.hpa.scaletargetref.name:
            enabled: true
          k8s.kubelet.version:
            enabled: true
          k8s.pod.qos_class:
            enabled: true
      # Mirrors the Splunk distro's agent kubelet configuration. container.id
      # is what lets Splunk tie a container metric back to a trace.
      kubeletstats:
        auth_type: serviceAccount
        collection_interval: 10s
        # See KUBELET_INSECURE_SKIP_VERIFY in scripts/lib.sh. Without this,
        # minikube/kind lose every pod and container metric to a TLS error.
        insecure_skip_verify: ${KUBELET_INSECURE_SKIP_VERIFY}
        extra_metadata_labels:
          - container.id
        metric_groups: [container, pod, node]
        metrics:
          # Duplicates of the utilization metrics Splunk actually charts.
          k8s.node.cpu.usage:
            enabled: false
          k8s.pod.cpu.usage:
            enabled: false
      # Datadog derives its host infrastructure metrics from the utilization
      # series, which the hostmetrics receiver leaves DISABLED by default, and
      # from the paging and processes scrapers, which the chart's hostMetrics
      # preset does not enable. Without these, Datadog's host CPU/disk/memory
      # graphs are wrong or empty.
      #
      # This also helps Splunk: the signalfx exporter's default translation
      # rules consume cpu.utilization and memory.utilization to build Splunk's
      # host metrics, so the same series serve both backends.
      #
      # Merged over the preset, whose filesystem exclude lists are preserved.
      hostmetrics:
        collection_interval: 10s
        scrapers:
          cpu:
            metrics:
              system.cpu.utilization:
                enabled: true
          filesystem:
            metrics:
              system.filesystem.utilization:
                enabled: true
          paging:
            metrics:
              system.paging.utilization:
                enabled: true
          processes:
          disk:
          load:
          memory:
          network:

      # Kubernetes events as logs. On a multi-node cluster this DaemonSet emits
      # one copy per node — see docs/ARCHITECTURE.md.
      k8sobjects:
        objects:
          - name: events
            mode: watch
            group: events.k8s.io
            exclude_watch_type: [DELETED]
    processors:
      # Splunk Observability rejects any datapoint carrying more than 36
      # dimensions, and silently logs "dropping datapoint". The k6 browser
      # metrics contribute ~11 of their own labels on top of the standard
      # Kubernetes resource set, which puts them at 37 — so they were being
      # discarded wholesale, along with some spanmetrics histogram buckets.
      #
      # These six resource attributes are the least useful of the set: SDK build
      # metadata, two UIDs that duplicate names we already send, a timestamp, and
      # an image tag. Removing them brings the total to 31 and leaves headroom.
      # Metrics only — traces keep the full set, where there is no such limit.
      resource/trim_dimensions:
        attributes:
          - key: telemetry.sdk.name
            action: delete
          - key: telemetry.sdk.version
            action: delete
          - key: k8s.pod.start_time
            action: delete
          - key: k8s.replicaset.uid
            action: delete
          - key: k8s.cluster.uid
            action: delete
          - key: container.image.tag
            action: delete

      # Node identity. The chart's resourcedetection uses [env, system]; inside
      # a pod the system detector resolves host.name to the COLLECTOR POD's
      # hostname, not the node.
      #
      # That breaks the two backends in different ways, which is why both fixes
      # are needed:
      #
      #   Datadog resolves a host from, in order: a literal `host` attribute,
      #   `datadog.host.name`, cloud-provider attributes, then
      #   `k8s.node.name`+`k8s.cluster.name`, then `host.id`, then `host.name`.
      #   Traces and kubeletstats metrics carry k8s.node.name (k8sattributes adds
      #   it) so they land on "<node>-<cluster>". hostmetrics has no pod to
      #   associate with, gets no k8s.node.name, and falls through to host.name —
      #   landing on a second, bogus host named after the collector pod. Host and
      #   container data then never correlate. Adding the k8snode detector puts
      #   k8s.node.name on every resource, so everything resolves to one host.
      #
      #   Splunk instead maps the host.name resource attribute straight to its
      #   `host` dimension, so it needs host.name itself corrected — hence the
      #   rewrite below rather than just the detector.
      # The detector is k8s_api; "k8snode" is its old name, and the chart's
      # rewriteDeprecatedComponentNames silently renames it in the detectors
      # list while leaving a "k8snode:" settings block orphaned and ignored.
      resourcedetection:
        detectors: [env, system, k8s_api]
        k8s_api:
          auth_type: serviceAccount
          node_from_env_var: K8S_NODE_NAME

      # Stamped on every signal, on every pipeline.
      #
      # deployment.environment(.name) drives Splunk APM's environment selector
      # and Datadog's env tag.
      #
      # k8s.cluster.name is what Splunk APM joins on to show Related Content for
      # Kubernetes: it pairs cluster name with k8s.pod.name/k8s.node.name to link
      # a span to the pod that emitted it. The kubernetesAttributes preset supplies
      # pod, namespace, node and cluster *uid*, but never cluster name — nothing in
      # the Kubernetes API carries one — so it has to be asserted here. It must
      # match the clusterName given to the splunk-otel-collector chart. Datadog
      # uses the same attribute for its kube_cluster_name tag.
      resource/deployment_env:
        attributes:
          - key: deployment.environment
            value: "${DEPLOYMENT_ENVIRONMENT}"
            action: upsert
          - key: deployment.environment.name
            value: "${DEPLOYMENT_ENVIRONMENT}"
            action: upsert
          - key: k8s.cluster.name
            value: "${TELEMETRY_CLUSTER_NAME}"
            action: upsert
          # Who and what produced this data. Lets several engineers share one
          # Datadog org or Splunk realm and still filter down to their own run.
          - key: demo.instance
            value: "${DEMO_INSTANCE}"
            action: upsert
          # Point host.name at the node rather than whichever pod emitted the
          # data. No-op when k8s.node.name is absent. Splunk keys its host
          # dimension off this; Datadog only reaches it as a last resort, so
          # this is effectively the Splunk half of the fix above.
          - key: host.name
            from_attribute: k8s.node.name
            action: upsert
PROC

  if [[ "${DEST_SPLUNK_AO}" == "true" ]]; then
    cat >> "${out}" <<AOPROC
      # Keep only GenAI spans on the branch that feeds Splunk Agent Observability.
      # Anything without a GenAI/OpenInference marker is dropped from that branch
      # only — the full trace still goes to APM.
      filter/genai:
        error_mode: ignore
        traces:
          span:
            - 'attributes["gen_ai.operation.name"] == nil and attributes["gen_ai.provider.name"] == nil and attributes["gen_ai.system"] == nil and attributes["openinference.span.kind"] == nil'
      # Routing attributes read by the Splunk Agent Observability OTLP provider.
      transform/splunk_ao:
        error_mode: ignore
        trace_statements:
          - context: resource
            statements:
              - set(attributes["splunk_ao.project.name"], "${SPLUNK_AO_PROJECT}")
              - set(attributes["splunk_ao.agentstream.name"], "${SPLUNK_AO_AGENT_STREAM}")
AOPROC
  fi

  # --- Collector config: exporters -------------------------------------------
  echo "    exporters:" >> "${out}"

  if [[ "${DEST_DATADOG}" == "true" ]]; then
    cat >> "${out}" <<DDEXP
      datadog:
        api:
          key: \${env:DD_API_KEY}
          site: ${DD_SITE}
          fail_on_invalid_key: true
        host_metadata:
          enabled: true
        # Ships the Kubernetes object manifests collected by k8sobjects/datadog
        # to Datadog's orchestrator intake, which is what populates the
        # Kubernetes Explorer. Off by default in the exporter.
        orchestrator_explorer:
          enabled: true
        retry_on_failure:
          enabled: true
DDEXP
  fi

  if [[ "${DEST_SPLUNK_O11Y}" == "true" ]]; then
    cat >> "${out}" <<SFXEXP
      # APM traces. OTLP/HTTP is the current Splunk trace ingest path (SAPM is retired).
      otlphttp/splunk_o11y:
        traces_endpoint: ${SPLUNK_O11Y_INGEST_URL}/v2/trace/otlp
        headers:
          X-SF-Token: \${env:SPLUNK_O11Y_ACCESS_TOKEN}
        retry_on_failure:
          enabled: true
      # Infrastructure Monitoring metrics.
      signalfx:
        access_token: \${env:SPLUNK_O11Y_ACCESS_TOKEN}
        api_url: ${SPLUNK_O11Y_API_URL}
        ingest_url: ${SPLUNK_O11Y_INGEST_URL}
        # Publishes host properties (OS, kernel, cores) so nodes appear as
        # first-class objects rather than bare metric series. root_path points
        # at the hostfs volume the hostMetrics preset already mounts.
        sync_host_metadata: true
        root_path: /hostfs
SFXEXP
  fi

  if [[ "${DEST_SPLUNK_HEC}" == "true" ]]; then
    local hec_tls="${SPLUNK_HEC_INSECURE_SKIP_VERIFY}"
    for sig in logs metrics traces; do
      local idx_var
      idx_var="SPLUNK_HEC_INDEX_$(echo "${sig}" | tr '[:lower:]' '[:upper:]')"
      cat >> "${out}" <<HECEXP
      splunk_hec/platform_${sig}:
        token: \${env:SPLUNK_HEC_TOKEN}
        endpoint: ${SPLUNK_HEC_ENDPOINT}
        index: ${!idx_var}
        source: kubernetes
        sourcetype: otel:${sig}
        splunk_app_name: otel-demo-multibackend
        max_connections: 200
        timeout: 10s
        tls:
          insecure_skip_verify: ${hec_tls}
        retry_on_failure:
          enabled: true
          initial_interval: 5s
          max_interval: 30s
          max_elapsed_time: 300s
        sending_queue:
          enabled: true
          num_consumers: 10
          queue_size: 1000
HECEXP
    done
  fi

  if [[ "${DEST_SPLUNK_AO}" == "true" ]]; then
    cat >> "${out}" <<AOEXP
      # Splunk Agent Observability is a separate product with its own OTLP
      # endpoint; auth is a header, not an OTLP access token.
      otlphttp/splunk_ao:
        traces_endpoint: ${SPLUNK_AO_API_URL}/otel/v1/traces
        encoding: proto
        headers:
          Splunk-AO-API-Key: \${env:SPLUNK_AO_API_KEY}
          project: "${SPLUNK_AO_PROJECT}"
          agentstream: "${SPLUNK_AO_AGENT_STREAM}"
        retry_on_failure:
          enabled: true
AOEXP
  fi

  # Keep the exporters map non-empty even with zero SaaS destinations.
  echo "      debug: {}" >> "${out}"

  # --- Collector config: connectors -------------------------------------------
  if [[ "${DEST_DATADOG}" == "true" ]]; then
    cat >> "${out}" <<'DDCON'
    connectors:
      # Produces Datadog APM trace metrics (hits/errors/latency). Without it the
      # APM "Services" page stays empty even though traces arrive.
      datadog/connector:
        traces:
          compute_stats_by_span_kind: true
          peer_tags_aggregation: true
DDCON
  fi

  # --- Collector config: pipelines --------------------------------------------
  # Upstream processor lists are replicated here with two deliberate changes:
  #   * traces uses transform/sanitize_spans (upstream references the logs
  #     transform, which is a no-op for spans and lets span-name cardinality
  #     through to the vendor APMs)
  #   * resource/deployment_env and batch are appended
  cat >> "${out}" <<PIPE
    service:
      pipelines:
        traces:
          processors: [memory_limiter, resourcedetection, resource, resource/deployment_env, transform/sanitize_spans, gen_ai_normalizer, batch]
          exporters: $(join_yaml_list "${tr_exp[@]}")
        metrics:
          receivers: $(join_yaml_list "${me_rcv[@]}")
          processors: [memory_limiter, resourcedetection, resource, resource/deployment_env, resource/trim_dimensions, batch]
          exporters: $(join_yaml_list "${me_exp[@]}")
        logs:
          receivers: [otlp, k8sobjects]
          processors: [memory_limiter, resourcedetection, resource, resource/deployment_env, transform/sanitize_logs, batch]
          exporters: $(join_yaml_list "${lo_exp[@]}")
PIPE

  if [[ "${DEST_DATADOG}" == "true" ]]; then
    cat >> "${out}" <<'DDPIPE'
        # Kubernetes object inventory -> Datadog Kubernetes Explorer only.
        logs/datadog_orchestrator:
          receivers: [k8sobjects/datadog]
          processors: [memory_limiter, resourcedetection, resource/deployment_env, batch]
          exporters: [datadog]
DDPIPE
  fi

  if [[ "${DEST_SPLUNK_AO}" == "true" ]]; then
    cat >> "${out}" <<'AOPIPE'
        # Second, independent traces branch: GenAI spans only.
        traces/splunk_ao:
          receivers: [otlp]
          processors: [k8s_attributes, memory_limiter, resourcedetection, resource, resource/deployment_env, gen_ai_normalizer, filter/genai, transform/splunk_ao, batch]
          exporters: [otlphttp/splunk_ao]
AOPIPE
  fi

  # --- Local backends ----------------------------------------------------------
  if [[ "${KEEP_LOCAL_BACKENDS}" != "true" ]]; then
    cat >> "${out}" <<'NOLOCAL'

# Bundled backends off: ~3 GiB less RAM. Their exporters stay defined in the
# collector config but are referenced by no pipeline, so they are never built.
jaeger:
  enabled: false
prometheus:
  enabled: false
grafana:
  enabled: false
opensearch:
  enabled: false
NOLOCAL
  fi

  ok "wrote ${out#"${REPO_ROOT}/"}"
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
  load_env
  render_values
fi
